  "content": "import { describe, expect, it, vi } from 'vitest';
import { Item } from '../src/auction-api/Item.js';
import { BidController } from '../src/auction-api/BidController.js';
import { BidService } from '../src/auction-api/BidService.js';
import { ItemStore } from '../src/auction-api/ItemStore.js';
import { UserStore } from '../src/auction-api/UserStore.js';
import { BidEventPublisher } from '../src/auction-api/BidEventPublisher.js';
import { EventFeed } from '../src/auction-api/EventFeed.js';
import { LiveGateway } from '../src/live-updates/LiveGateway.js';
import { EventFeedClient } from '../src/live-updates/EventFeedClient.js';

const FAR_FUTURE = new Date('2100-01-01T00:00:00.000Z');
const PAST = new Date('2000-01-01T00:00:00.000Z');
const TWO_MINUTES_MS = 2 * 60 * 1000;

function makeItem(overrides: Partial<{ id: string; sellerId: string; startingPrice: number; endTime: Date; highestBidAmount: number | null; highestBidderId: string | null }> = {}): Item {
  return new Item(
    overrides.id ?? 'item-1',
    overrides.sellerId ?? 'seller-1',
    'Lamp',
    overrides.startingPrice ?? 50,
    'USD' as Item['currency'],
    overrides.endTime ?? FAR_FUTURE,
    'open' as Item['status'],
    overrides.highestBidAmount ?? null,
    overrides.highestBidderId ?? null,
    null,
  );
}

function fakeStores(items: Item[], userIds: string[]) {
  const itemMap = new Map<string, Item>();
  for (const item of items) itemMap.set(item.id, item);
  const users = new Set(userIds);
  const bids: unknown[] = [];
  const itemStore = {
    findItem: async (id: string) => itemMap.get(id) ?? null,
    saveItem: async (item: Item) => {
      itemMap.set(item.id, item);
      return item;
    },
    saveBid: async (bid: unknown) => {
      bids.push(bid);
      return bid;
    },
  } as unknown as ItemStore;
  const userStore = {
    findById: async (id: string) => (users.has(id) ? { id } : null),
  } as unknown as UserStore;
  return { itemStore, userStore, bids };
}

function makeService(items: Item[], userIds: string[] = ['bidder-1', 'bidder-2']) {
  const stores = fakeStores(items, userIds);
  const eventFeed = { publish: vi.fn() } as unknown as EventFeed;
  const publisher = new BidEventPublisher(eventFeed);
  const service = new BidService(stores.itemStore, publisher, stores.userStore);
  return { service, bids: stores.bids, eventFeed };
}

function makeGateway() {
  const sockets = new Map<string, { readyState: number; send: ReturnType<typeof vi.fn> }>();
  const gateway = new LiveGateway(sockets as unknown as ConstructorParameters<typeof LiveGateway>[0]);
  return { gateway, sockets };
}

function addSocket(sockets: Map<string, { readyState: number; send: ReturnType<typeof vi.fn> }>, clientId: string) {
  const socket = { readyState: 1, send: vi.fn() };
  sockets.set(clientId, socket);
  return socket;
}

describe('UC-003 Place bid', () => {
  it("REQ-002 AC1: A bid on an item whose end time has not passed, from a user other than the seller, is stored in the item currency if it is valid.", async () => {
    const { service, bids } = makeService([makeItem()]);
    const bid = await service.placeBid('item-1', 'bidder-1', 60);
    expect(bid.amount).toBe(60);
    expect(bid.bidderId).toBe('bidder-1');
    expect(bids).toHaveLength(1);
  });

  it("REQ-002 AC2: A bid on an item whose end time has passed is rejected.", async () => {
    const { service, bids } = makeService([makeItem({ endTime: PAST })]);
    await expect(service.placeBid('item-1', 'bidder-1', 60)).rejects.toThrow();
    expect(bids).toHaveLength(0);
  });

  it("REQ-002 AC3: The first bid is accepted only if it is at least the starting price.", async () => {
    const { service } = makeService([makeItem({ startingPrice: 50 })]);
    await expect(service.placeBid('item-1', 'bidder-1', 49)).rejects.toThrow();
  });

  it("REQ-002 AC4: Any later bid is accepted only if it is at least 1 unit of the item currency higher than the current highest bid, otherwise it is rejected.", async () => {
    const { service } = makeService([makeItem({ startingPrice: 50 })]);
    await service.placeBid('item-1', 'bidder-1', 100);
    await expect(service.placeBid('item-1', 'bidder-2', 100)).rejects.toThrow();
  });

  it("REQ-002 AC5: A bid by the item's seller on their own item is rejected.", async () => {
    const { service, bids } = makeService([makeItem({ sellerId: 'seller-1' })], ['seller-1']);
    await expect(service.placeBid('item-1', 'seller-1', 60)).rejects.toThrow();
    expect(bids).toHaveLength(0);
  });

  it("REQ-009 AC1: A valid bid placed less than or exactly 2 minutes before the end time moves the end time 2 minutes later.", () => {
    const now = new Date('2030-01-01T12:00:00.000Z');
    const endTime = new Date(now.getTime() + TWO_MINUTES_MS);
    const item = makeItem({ endTime });
    const extended = item.extendIfLate(now);
    expect(extended).toBe(true);
    expect(item.endTime.getTime()).toBe(endTime.getTime() + TWO_MINUTES_MS);
  });

  it("REQ-009 AC2: A valid bid placed more than 2 minutes before the end time does not change the end time.", () => {
    const now = new Date('2030-01-01T12:00:00.000Z');
    const endTime = new Date(now.getTime() + TWO_MINUTES_MS + 60 * 1000);
    const item = makeItem({ endTime });
    const extended = item.extendIfLate(now);
    expect(extended).toBe(false);
    expect(item.endTime.getTime()).toBe(endTime.getTime());
  });

  it.todo('REQ-009 AC3: manual: watchers seeing the new end time without reloading needs a real browser session');

  it("REQ-003 AC1: When a bid is accepted, every client watching the item shows the new bid without a page reload.", () => {
    const { gateway, sockets } = makeGateway();
    const first = addSocket(sockets, 'client-1');
    const second = addSocket(sockets, 'client-2');
    gateway.watch('client-1', 'item-1');
    gateway.watch('client-2', 'item-1');
    gateway.broadcast('item-1', 'bid 60 on item-1');
    expect(first.send).toHaveBeenCalledWith(expect.stringContaining('bid 60 on item-1'));
    expect(second.send).toHaveBeenCalledWith(expect.stringContaining('bid 60 on item-1'));
  });

  it("REQ-003 AC2: A client watching a different item does not receive that bid.", () => {
    const { gateway, sockets } = makeGateway();
    const other = addSocket(sockets, 'client-1');
    gateway.watch('client-1', 'item-2');
    gateway.broadcast('item-1', 'bid 60 on item-1');
    expect(other.send).not.toHaveBeenCalled();
  });

  it.todo('REQ-011 AC1: manual: 200 concurrent watchers with a 1 second delivery bound needs a dedicated load environment');

  it.todo('REQ-011 AC2: manual: no lost bids under sustained load needs a dedicated load environment');

  it("SEQ-003 scenario: Place bid", async () => {
    const item = makeItem();
    const stores = fakeStores([item], ['bidder-1']);
    const eventFeed = { publish: vi.fn() } as unknown as EventFeed;
    const publisher = new BidEventPublisher(eventFeed);
    const service = new BidService(stores.itemStore, publisher, stores.userStore);
    const controller = new BidController(service);
    const bid = await controller.placeBid('item-1', 'bidder-1', 60);
    expect(bid.amount).toBe(60);
    expect(stores.bids).toHaveLength(1);
    expect(eventFeed.publish).toHaveBeenCalledWith(expect.any(String), expect.any(String));
    expect(EventFeedClient).toBeDefined();
  });
});
